<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Admin extends MY_Controller { public function __construct(){parent::__construct();$this->load->model('Product_model');$this->load->model('Order_model');}
 public function index(){$this->require_admin();$this->view('admin/index',array('products'=>$this->Product_model->all(),'orders'=>$this->Order_model->all()));}
 public function products(){$this->require_admin();$this->view('admin/products',array('products'=>$this->Product_model->all()));}
 public function add_product(){$this->require_admin();if($this->input->method()==='post'){ $data=array('name'=>$this->input->post('name',true),'description'=>$this->input->post('description',true),'category'=>$this->input->post('category',true),'price'=>(float)$this->input->post('price'),'old_price'=>(float)$this->input->post('old_price'),'image'=>$this->input->post('image',true),'stock'=>(int)$this->input->post('stock'),'is_featured'=>$this->input->post('is_featured')?1:0);$this->Product_model->create($data);redirect('admin/products');}$this->view('admin/product_form',array('product'=>null));}
 public function edit_product($id){$this->require_admin();$p=$this->Product_model->find($id);if(!$p)show_404();if($this->input->method()==='post'){$this->Product_model->update($id,array('name'=>$this->input->post('name',true),'description'=>$this->input->post('description',true),'category'=>$this->input->post('category',true),'price'=>(float)$this->input->post('price'),'old_price'=>(float)$this->input->post('old_price'),'image'=>$this->input->post('image',true),'stock'=>(int)$this->input->post('stock'),'is_featured'=>$this->input->post('is_featured')?1:0));redirect('admin/products');}$this->view('admin/product_form',array('product'=>$p));}
 public function delete_product($id){$this->require_admin();$this->Product_model->delete($id);redirect('admin/products');}
 public function orders(){$this->require_admin();$this->view('admin/orders',array('orders'=>$this->Order_model->all()));}
 public function update_order_status($id){$this->require_admin();$status=$this->input->post('status',true);if(in_array($status,array('Processing','Confirmed','Shipped','Delivered','Cancelled'),true))$this->Order_model->update_status($id,$status);redirect('admin/orders');}
}
